'use strict';
(function(){
const D=window.PoeticsResearch,T=D.tables;let tab='Directory',q='',selected=null,place='All places';
const gids={'Evidence Ledger':128843754,'Annual Synthesis':1855607110,'People & Platforms':1151770477,'Historical Timeline':1394386329,'Research Questions':947420848};
const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function ids(value){const out=[];String(value||'').replace(/E(\d{3})\s*[–—-]\s*E?(\d{3})|E(\d{3})/g,(_,a,b,c)=>{if(c)out.push('E'+c);else for(let n=+a;n<=+b;n++)out.push('E'+String(n).padStart(3,'0'));return '';});return [...new Set(out)];}
function source(table,row){return `${D.spreadsheet}#gid=${gids[table]}&range=A${row}:V${row}`;}
const refs=r=>ids(r['Evidence IDs']).map(id=>`<button class="evidence-chip" data-evidence="${id}">${id}</button>`).join('');
function fields(r,keys){return `<dl class="research-fields">${keys.filter(k=>r[k]).map(k=>`<div><dt>${h(k)}</dt><dd>${h(r[k])}</dd></div>`).join('')}</dl>`;}
const name=(r,t)=>r[t==='Evidence Ledger'?'Source Headline':t==='People & Platforms'?'Entity':t==='Historical Timeline'?'Milestone':t==='Annual Synthesis'?'Year':'Research Question / Hypothesis'];
const tables={Directory:'People & Platforms',Timeline:'Historical Timeline',Evidence:'Evidence Ledger',Synthesis:'Annual Synthesis',Questions:'Research Questions'};
window.PoeticsResearchUtils={ids};
window.renderResearchAtlas=function(root,pilot){
function draw(){
const table=tables[tab]||'People & Platforms';const all=table==='People & Platforms'?T[table].concat(D.supplementalProfiles||[]):T[table];let rows=all.filter(r=>Object.values(r).join(' ').toLowerCase().includes(q.toLowerCase())&&(place==='All places'||[r['City / Base'],r['City / Geography'],r.Geography].includes(place)));
if(tab==='Timeline')rows.sort((a,b)=>String(a['Date / Year']).localeCompare(String(b['Date / Year'])));
const places=[...new Set(all.map(r=>r['City / Base']||r['City / Geography']||r.Geography).filter(Boolean))].sort();
const record=selected&&selected.table===table?all.find(r=>r.sheetRow===selected.row):null;
root.innerHTML=`<div class="page-top"><p class="quiet-kicker">Nigerian poetry ecosystem</p><h1>Atlas.</h1><p>People, platforms and the evidence connecting them.</p><p class="caption">92 alert records · 30 canonical + 5 supplementary profiles · 26 milestones · Research snapshot ${h(D.readAt)}.</p><details class="notice"><summary>About this research</summary><p>The canonical sheet contains preserved alert excerpts and working analysis. Original article URLs are missing from all 92 alert records. Alert dates are not event dates; first ledger evidence is not a founding date. Phase 2 review is pending because its document is inaccessible.</p><p>Open Mic Ogbomoso’s retrospective 2015 origin and the pilot’s 2022 recurring form remain distinct. Poetry Wednesday/PW has unresolved identity and geography; it is not merged with Kano’s Poetic Wednesdays Initiative.</p><a href="${h(D.spreadsheet)}" target="_blank" rel="noopener">Canonical spreadsheet </a> · <a href="${h(D.phase2.url)}" target="_blank" rel="noopener">Phase 2 document </a> · <a href="canonical-research.json" download>Download research snapshot</a></details></div><div class="workspace"><div class="tabs" aria-label="Atlas view">${Object.keys(tables).concat('Map / pilot').map(v=>`<button data-tab="${v}" aria-pressed="${tab===v}">${v}</button>`).join('')}</div><div class="toolbar"><label class="search">Search ${h(tab.toLowerCase())}<input id="research-search" value="${h(q)}" placeholder="A name, place, year or evidence ID…"></label>${places.length?`<label>Geography<select id="research-place">${['All places',...places].map(p=>`<option ${p===place?'selected':''}>${h(p)}</option>`).join('')}</select></label>`:''}<button id="research-reset">Reset</button></div><p class="caption" role="status">${rows.length} matching ${h(tab.toLowerCase())} records. ${tab==='Evidence'?'Preserved alerts; original articles not retrieved.':tab==='Directory'?'Working profiles; verification and Phase 2 reconciliation pending.':''}</p><div class="research-layout"><div class="results">${rows.map(r=>`<button class="record ${record===r?'selected':''}" data-row="${r.sheetRow}"><span>${h(name(r,table))}<small>${h(r['Entity Type']||r['Date / Year']||r['Evidence ID']||r['RQ ID']||r['Verification Status'])} · ${h(r['City / Base']||r['City / Geography']||r.Geography||'')}</small></span><span></span></button>`).join('')||'<p>No records match.</p>'}</div><section id="research-detail" class="panel" aria-label="Selected research record">${record?detail(record,table):'<h2>Follow a thread.</h2><p>Select a record to inspect its provenance, evidence and open questions.</p>'}</section></div></div>`;
root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.tab==='Map / pilot'){pilot();const back=document.createElement('button');back.textContent=' Canonical research';back.onclick=()=>draw();root.prepend(back);return;}tab=b.dataset.tab;q='';place='All places';selected=null;draw();});
root.querySelector('#research-search').oninput=e=>{q=e.target.value;const pos=e.target.selectionStart;draw();const input=root.querySelector('#research-search');input.focus();input.setSelectionRange(pos,pos);};
const select=root.querySelector('#research-place');if(select)select.onchange=e=>{place=e.target.value;selected=null;draw();};
root.querySelector('#research-reset').onclick=()=>{q='';place='All places';selected=null;draw();};
root.querySelectorAll('[data-row]').forEach(b=>b.onclick=()=>{selected={table,row:+b.dataset.row};draw();root.querySelector('#research-detail').scrollIntoView({block:'nearest',behavior:'auto'});});
root.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{tab='Directory';q='';place='All places';selected={table:'People & Platforms',row:+b.dataset.profile};draw();root.querySelector('#research-detail').scrollIntoView({block:'nearest'});});
root.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>{const r=T['Evidence Ledger'].find(x=>x['Evidence ID']===b.dataset.evidence);tab='Evidence';q='';place='All places';selected={table:'Evidence Ledger',row:r.sheetRow};draw();root.querySelector('#research-detail').scrollIntoView({block:'nearest'});});
}
function detail(r,t){const keys=Object.keys(r).filter(k=>!['sheetRow','Entity','Milestone','Source Headline','Year','Research Question / Hypothesis','Evidence IDs','Source Links'].includes(k));const inferred=t==='Historical Timeline'&&/inferred|implied|verify|retrospective/i.test(String(r['Verification Status'])+' '+r['Date / Year']);return `<span class="badge">${h(inferred?'Inferred / requires verification':r['Verification Status']||'Working research — not independently verified')}</span><h2>${h(name(r,t))}</h2>${t==='Evidence Ledger'?'<p class="caption">Alert date records when an alert was captured, not when the event occurred. Original source URL has not been recovered.</p>':''}${fields(r,keys)}${r['Evidence IDs']?`<h3>Evidence trail</h3><div class="connections">${refs(r)}</div>`:''}${t==='Evidence Ledger'?`<h3>Linked profiles</h3>${T['People & Platforms'].filter(p=>ids(p['Evidence IDs']).includes(r['Evidence ID'])).map(p=>`<button data-profile="${p.sheetRow}">${h(p.Entity)}</button>`).join('')||'<p>No linked profile in this snapshot.</p>'}`:''}${r['Source Links']?`<h3>Public sources</h3>${r['Source Links'].map(s=>`<p><a href="${h(s.url)}" target="_blank" rel="noopener">${h(s.title)} </a></p>`).join('')}`:`<p><a href="${h(source(t,r.sheetRow))}" target="_blank" rel="noopener">Canonical sheet · row ${r.sheetRow} </a></p>`}<p class="caption">Metadata and short research summaries only. No poems, images or private mail identifiers reproduced.</p>`;}
draw();
};
})();
